def wasm_runtime_import_name(name: str) -> str | None:
    import_name = wasm_import_name(name)
    if import_name is not None:
        return import_name
    import_name = WASM_RUNTIME_IMPORT_BY_EXPORT.get(name)
    if import_name is not None:
        return import_name
    if name in WASM_RUNTIME_HOST_EXPORTS:
        return name
    return None

def wasm_runtime_export_name(name: str) -> str | None:
    import_name = wasm_runtime_import_name(name)
    if import_name is None:
        return None
    export_name = WASM_RUNTIME_EXPORT_BY_IMPORT.get(import_name)
    if export_name is not None:
        return export_name
    if import_name in WASM_RUNTIME_HOST_EXPORTS:
        return import_name
    return None

def wasm_import_signature(name: str) -> tuple[tuple[str, ...], tuple[str, ...]] | None:
    import_name = wasm_runtime_import_name(name)
    if import_name is not None:
        signature = WASM_IMPORT_SIGNATURE_BY_NAME.get(import_name)
        if signature is not None:
            return signature
    return WASM_RUNTIME_HOST_EXPORT_SIGNATURE_BY_NAME.get(name)

def wasm_import_result_kind(name: str) -> str | None:
    signature = wasm_import_signature(name)
    if signature is None:
        return None
    results = signature[1]
    return "nil" if not results else ", ".join(results)

